                y2 = 0;
            }
            else
            {
                x1 = ((MouseEventArgs)e).X;
                y1 = ((MouseEventArgs)e).Y;
            }
        }

        private void DrawCircle(int x1, int y1, int x2, int y2)
        {
            pictureBox1.Image = (Image)new Bitmap(pictureBox1.Width, pictureBox1.Height);
            Graphics g = Graphics.FromImage(pictureBox1.Image);
            int r = (int)Math.Sqrt(Math.Pow(x2 - x1, 2) + Math.Pow(y2 - y1, 2)); // calculate radius using the distance between the two points

            int x = 0;
            int y = r;
            int F = 1 - r;
            int delFs = 3;
            int delFd = 5 - 2 * r;
            while (x <= y)
            {
                g.FillRectangle(Brushes.Black, x1 + x, y1 + y, 1, 1);
                g.FillRectangle(Brushes.Black, x1 + y, y1 + x, 1, 1);
                g.FillRectangle(Brushes.Black, x1 - x, y1 + y, 1, 1);
                g.FillRectangle(Brushes.Black, x1 - y, y1 + x, 1, 1);
                g.FillRectangle(Brushes.Black, x1 + x, y1 - y, 1, 1);
                g.FillRectangle(Brushes.Black, x1 + y, y1 - x, 1, 1);
                g.FillRectangle(Brushes.Black, x1 - x, y1 - y, 1, 1);
                g.FillRectangle(Brushes.Black, x1 - y, y1 - x, 1, 1);

                if (F > 0)
                {
                    F += delFd;
                    y--;
                    delFd += 2;
                    delFs += 2;
                }
                else
                {
                    F += delFs;
                    delFd += 2;
                    delFs += 2;
                }
                x++;
            }
        }
    }
