Here is a sample C code using CSIM to perform the pull-based cache invalidation scheme according to the given parameters:

```C
#include <stdio.h>
#include <stdlib.h>
#include <csim.h>

#define NUM_CLIENTS 5
#define DB_SIZE 500
#define DATA_SIZE 1024
#define BANDWIDTH 10000
#define CACHE_SIZE 100
#define HOT_DATA_ITEMS 50
#define HOT_DATA_ACCESS_PROB 0.8
#define COLD_DATA_ITEMS (DB_SIZE - HOT_DATA_ITEMS)
#define HOT_DATA_UPDATE_PROB 0.33

int query_count = 0, hit_count = 0, cold_count = 0, update_count = 0;
double query_delay = 0;

int cache[CACHE_SIZE];
int hot_data[HOT_DATA_ITEMS];
int cold_data[COLD_DATA_ITEMS];

void init_data() {
    int i;
    for (i = 0; i < CACHE_SIZE; i++) {
        cache[i] = -1;
    }
    for (i = 0; i < HOT_DATA_ITEMS; i++) {
        hot_data[i] = rand() % DB_SIZE;
        cold_data[i] = -1;
    }
    for (i = 0; i < COLD_DATA_ITEMS; i++) {
        cold_data[i] = rand() % DB_SIZE;
    }
}

int is_in_cache(int data_id) {
    int i;
    for (i = 0; i < CACHE_SIZE; i++) {
        if (cache[i] == data_id) {
            return 1;
        }
    }
    return 0;
}

void update_cache(int data_id) {
    int i, lru_index = 0, lru_time = simtime() + 1;
    for (i = 0; i < CACHE_SIZE; i++) {
        if (cache[i] == data_id) {
            return;
        }
        if (cache[i] == -1) {
            cache[i] = data_id;
            return;
        }
        if (lastchange(cache[i]) < lru_time) {
            lru_index = i;
            lru_time = lastchange(cache[i]);
        }
    }
    cache[lru_index] = data_id;
}

int find_data(int data_id) {
    int i;
    for (i = 0; i < HOT_DATA_ITEMS; i++) {
        if (hot_data[i] == data_id) {
            return HOT_DATA_ACCESS_PROB >= ((double) rand() / RAND_MAX);
        }
    }
    for (i = 0; i < COLD_DATA_ITEMS; i++) {
        if (cold_data[i] == data_id) {
            return 1;
        }
    }
    cold_count++;
    return 0;
}

double generate_query() {
    int data_id = rand() % DB_SIZE;
    if (is_in_cache(data_id)) {
        query_count++;
        wait(0.001);
        return 0;
    }
    wait(expntl(1.0/T_QUERY));
    if (find_data(data_id)) {
        hit_count++;
        update_cache(data_id);
    }
    query_count++;
    return simtime() - event_time;
}

void generate_update(int data_id) {
    if (HOT_DATA_UPDATE_PROB >= ((double) rand() / RAND_MAX)) {
        hot_data[rand() % HOT_DATA_ITEMS] = data_id;
    } else {
        cold_data[rand() % COLD_DATA_ITEMS] = data_id;
    }
    update_count++;
}

void server() {
    int data_id = rand() % DB_SIZE;
    generate_update(data_id);
    write("Data updated: ");
    writeline(data_id);
    hold(expntl(1.0/T_UPDATE));
}

void client() {
    while (1) {
        generate_query();
    }
}

int main() {
    init_data();
    T_QUERY = 5;
    T_UPDATE = 5;
    set_seed(12345);
    create("main");
    int i;
    for (i = 0; i < NUM_CLIENTS; i++) {
        process(client);
    }
    process(server);
    hold(10000.0);
    printf("Total queries: %d, hits: %d, hit rate: %.2f%%\n", 
           query_count, hit_count, (double) hit_count / query_count * 100);
    printf("Cold data queries: %d, update count: %d\n", cold_count, update_count);
    return 0;
}
```

The `init_data()` function initializes the cache and data items. `is_in_cache()` checks if a data item is already in the cache. `update_cache()` updates the cache with a new data item. `find_data()` checks if a data item can be found in the hot or cold data items based on the given probability. `generate_query()` generates a query with an exponentially distributed wait time and checks if the data item is in the cache or can be found in the server. `generate_update()` generates a new data item update and stores it in the hot or cold data items based on the given probability. `server()` generates a data item update with an exponentially distributed wait time. `client()` repeatedly generates queries.

