Next, create a new file called `bookkeeping.js` in the same directory as your HTML file, and add the following code:

```javascript
let incomeSlider = document.getElementById("income");
let incomeValue = document.getElementById("incomeValue");
let expensesSlider = document.getElementById("expenses");
let expensesValue = document.getElementById("expensesValue");
let profitValue = document.getElementById("profit");

function updateIncome() {
    incomeValue.textContent = incomeSlider.value;
    updateProfit();
}

function updateExpenses() {
    expensesValue.textContent = expensesSlider.value;
    updateProfit();
}

function updateProfit() {
    let profit = parseInt(incomeSlider.value) - parseInt(expensesSlider.value);
    profitValue.textContent = profit;
}
