            int cell = (int) (255 * (grey - t1) / (t2 - t1));
            if (t2 >= grey && grey >= t1) {
                cell = (int) (((double) cell) / step);
                if (cell <= index) {
                    resultImage.setRGB(x, y, Color.BLACK.getRGB());
